35 method swap<T>(a: array<T>, i: int, j: int)
36   // requires a != null
37   requires 0 <= j < a.Length
38   modifies a
39   ensures a[i] == old(a[j])
40   ensures a[j] == old(a[i])
41   ensures forall m :: 0 <= m < a.Length && m != i && m != j ==> a[m] == old(a[m])
42   ensures multiset(a[..]) == old(multiset(a[..]))
43 {
44   var t := a[i];
45   a[i] := a[j];
46   a[j] := t;
47 }
