49 method getAllShuffledDataEntries<T(0)>(m_dataEntries: array<T>) returns (result: array<T>)
50   // requires m_dataEntries != null
51   // ensures result != null
52   ensures result.Length == m_dataEntries.Length
53   ensures multiset(result[..]) == multiset(m_dataEntries[..])
54 {
55   result := new T[m_dataEntries.Length];
56   forall i | 0 <= i < m_dataEntries.Length {
57     result[i] := m_dataEntries[i];
58   }
59 
60   assert result[..] == m_dataEntries[..];
61   
62   var k := result.Length - 1;
63   while (k >= 0)
64     invariant multiset(result[..]) == multiset(m_dataEntries[..])
65   {
66     var i := random(0, k);
67     assert i >= 0 && i <= k;
68 
69     if (i != k) {
70       swap(result, i, k);
71     }
72     
73     k := k - 1;
74   }
75 }
