82 lemma in_set_of_seq<T>(x: T, s: seq<T>)
83   ensures x in s <==> x in set_of_seq(s)
84 
85 lemma subset_set_of_seq<T>(s1: seq<T>, s2: seq<T>)
86   requires set_of_seq(s1) <= set_of_seq(s2)
87   ensures forall x :: x in s1 ==> x in s2
