89 method getRandomDataEntry<T(==)>(m_workList: array<T>, avoidSet: seq<T>) returns (e: T)
90   requires m_workList.Length > 0
91 //  ensures set_of_seq(avoidSet) < set_of_seq(m_workList[..]) ==> e !in avoidSet
92 //  ensures avoidSet < m_workList[..] ==> e in m_workList[..]
93 {
94   var k := m_workList.Length - 1;
95 
96   while (k >= 0)
97   {
98     var i := random(0, k);
99     assert i >= 0 && i <= k;
100 
101     e := m_workList[i];
102     if (e !in avoidSet) {
103       return e;
104     }
105     
106     k := k - 1;
107   }
108   
109   return m_workList[0];
110 }

